    case 'STATUS_CODE_OK':
      return OTelSpanStatusCode.OK;
    case 'STATUS_CODE_ERROR':
      return OTelSpanStatusCode.ERROR;
    case 'STATUS_CODE_UNSET':
      return OTelSpanStatusCode.UNSET;

