 * Type definitions for the MLflow Codex integration.
 *
 * These types describe the shape of the JSONL rollout transcript that Codex
 * writes to disk, as well as the notification payload delivered to the
 * `notify` program when an agent turn completes.
 */

/**
 * Payload delivered by Codex to the configured `notify` program when an
 * agent turn completes.
 */
export interface NotifyPayload {
  /** The notification type, e.g. `agent-turn-complete`. */
  type: string;
  /** Identifier of the conversation thread. */
  'thread-id': string;
  /** Identifier of the turn that just completed. */
  'turn-id': string;
  /** Working directory of the Codex session. */
  cwd: string;
  /** The client that produced the turn. */
  client: string;
  /** The user input messages for the completed turn. */
  'input-messages': string[];
  /** The final assistant message produced during the turn. */
  'last-assistant-message': string;
}

/**
 * A single content block inside a message record.
 */
export interface ContentBlock {
  type: string;
  text: string;
}

/**
 * The payload portion of a rollout line. The available fields depend on the
 * record type (session metadata, event message, or response item), so most of
 * them are optional.
 */
export interface RolloutPayload {
  /** Discriminates the record variant (e.g. `message`, `function_call`, `task_started`). */
  type: string;
  role?: string;
  content?: ContentBlock[] | string;
  name?: string;
  call_id?: string;
  arguments?: string;
  output?: unknown;
  exit_code?: number;
  status?: string;
  info?: Record<string, any>;
  id?: string;
  cwd?: string;
  originator?: string;
  cli_version?: string;
  source?: string;
  model?: string;
  message?: string;
  // Allow any additional fields present in real Codex transcripts.
  [key: string]: unknown;
}

/**
 * A single line of a JSONL transcript file.
 */
export interface RolloutLine {
  /** ISO 8601 timestamp of the record. */
  timestamp: string;
  /** The record variant. */
  type: 'session_meta' | 'event_msg' | 'response_item';
  /** The record payload. */
  payload: RolloutPayload;
}

/**
 * A single tool call inside an assistant message, in OpenAI chat format.
 */
export interface ToolCall {
  id: string;
  type: 'function';
  function: {
    name: string;
    arguments: string;
  };
}

/**
 * An OpenAI chat-format message reconstructed from a transcript record.
 */
export interface ChatMessage {
  role: string;
  content: string | null;
  tool_call_id?: string;
  tool_calls?: ToolCall[];
}
