 * Helpers for reading and interpreting Codex JSONL rollout transcripts.
 */

import * as fs from 'fs';
import type { ContentBlock, RolloutLine } from './types';

const NANOSECONDS_PER_MS = 1e6;

/**
 * Read a JSONL transcript file from disk and parse each line into a
 * {@link RolloutLine}. Blank lines are skipped.
 *
 * @param filePath Path to the JSONL transcript file.
 * @returns One parsed {@link RolloutLine} per non-empty line in the file.
 */
export function readTranscript(filePath: string): RolloutLine[] {
  const contents = fs.readFileSync(filePath, 'utf-8');
  const records: RolloutLine[] = [];

  for (const line of contents.split('\n')) {
    const trimmed = line.trim();
    if (trimmed.length === 0) {
      continue;
    }
    records.push(JSON.parse(trimmed) as RolloutLine);
  }

  return records;
}

/**
 * Parse an ISO 8601 timestamp string into an integer number of nanoseconds
 * since the Unix epoch.
 *
 * @param input An ISO 8601 timestamp, or null/undefined/empty string.
 * @returns The timestamp in nanoseconds, or null when the input is empty or
 *          cannot be parsed.
 */
export function parseTimestampToNs(input: string | null | undefined): number | null {
  if (input === null || input === undefined || input === '') {
    return null;
  }

  const ms = Date.parse(input);
  if (Number.isNaN(ms)) {
    return null;
  }

  return Math.floor(ms * NANOSECONDS_PER_MS);
}

/**
 * Extract plain text from a message content value.
 *
 * - For an array of content blocks, joins every text field with `'\n'`.
 * - For a plain string, returns it unchanged.
 * - For `undefined`, returns an empty string.
 *
 * @param content A content block array, a string, or undefined.
 * @returns The extracted text.
 */
export function extractTextFromContent(
  content: ContentBlock[] | string | undefined,
): string {
  if (content === undefined) {
    return '';
  }

  if (typeof content === 'string') {
    return content;
  }

  if (Array.isArray(content)) {
    return content
      .filter((block) => block != null && typeof block.text === 'string')
      .map((block) => block.text)
      .join('\n');
  }

  return '';
}

/**
 * Find the last user message in the transcript.
 *
 * @param records The transcript records.
 * @returns An object whose `text` property holds the last user message text,
 *          or null if there is no user message.
 */
export function findLastUserPrompt(records: RolloutLine[]): { text: string } | null {
  for (let i = records.length - 1; i >= 0; i--) {
    const payload = records[i].payload;
    if (payload.role === 'user') {
      const text =
        typeof payload.message === 'string'
          ? payload.message
          : extractTextFromContent(payload.content);
      return { text };
    }
  }

  return null;
}

/**
 * Return only the records belonging to the most recent turn: from the
 * `task_started` event (inclusive) through the following `task_complete`
 * event (inclusive).
 *
 * @param records The full set of transcript records.
 * @returns The subset of records for the most recent turn. The first record,
 *          when present, is the `task_started` event_msg.
 */
export function getLastTurnRecords(records: RolloutLine[]): RolloutLine[] {
  let startIdx = -1;
  for (let i = records.length - 1; i >= 0; i--) {
    const record = records[i];
    if (record.type === 'event_msg' && record.payload.type === 'task_started') {
      startIdx = i;
      break;
    }
  }

  if (startIdx === -1) {
    return [];
  }

  let endIdx = records.length - 1;
  for (let i = startIdx; i < records.length; i++) {
    const record = records[i];
    if (record.type === 'event_msg' && record.payload.type === 'task_complete') {
      endIdx = i;
      break;
    }
  }

  return records.slice(startIdx, endIdx + 1);
}

/**
 * Locate the token_count event and extract its usage counts.
 *
 * @param records The transcript records.
 * @returns The token usage counts, or null if no token_count event exists.
 */
export function getTokenUsage(
  records: RolloutLine[],
): { input_tokens: number; output_tokens: number; total_tokens: number } | null {
  let usage: Record<string, any> | null = null;

  for (const record of records) {
    if (record.type === 'event_msg' && record.payload.type === 'token_count') {
      const info = record.payload.info as Record<string, any> | undefined;
      // Real Codex transcripts nest the counts under `total_token_usage`;
      // fall back to a flat shape for simpler fixtures.
      usage = (info?.total_token_usage as Record<string, any>) ?? info ?? {};
    }
  }

  if (usage === null) {
    return null;
  }

  const inputTokens = Number(usage.input_tokens ?? 0);
  const outputTokens = Number(usage.output_tokens ?? 0);
  const totalTokens = Number(usage.total_tokens ?? inputTokens + outputTokens);

  return {
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    total_tokens: totalTokens,
  };
}

/**
 * Find the session_meta record.
 */
function findSessionMeta(records: RolloutLine[]): RolloutLine | undefined {
  return records.find((record) => record.type === 'session_meta');
}

/**
 * Return the model name recorded in the session metadata.
 *
 * @param records The transcript records.
 * @returns The model name, or `'unknown'` if none is recorded.
 */
export function getModel(records: RolloutLine[]): string {
  const meta = findSessionMeta(records);
  const model = meta?.payload.model;
  return typeof model === 'string' && model.length > 0 ? model : 'unknown';
}

/**
 * Return the session ID stored in the session metadata.
 *
 * @param records The transcript records.
 * @returns The session ID string.
 */
export function getSessionId(records: RolloutLine[]): string {
  const meta = findSessionMeta(records);
  const id = meta?.payload.id;
  return typeof id === 'string' ? id : '';
}

/**
 * Coerce a function_call_output payload value into an output string.
 */
export function extractOutputString(output: unknown): string {
  if (typeof output === 'string') {
    return output;
  }
  if (output != null && typeof output === 'object') {
    const content = (output as { content?: unknown }).content;
    if (typeof content === 'string') {
      return content;
    }
    return JSON.stringify(output);
  }
  return output == null ? '' : String(output);
}

/**
 * Build a map from tool call_id to the corresponding tool output string by
 * scanning function_call_output records.
 *
 * @param records The transcript records.
 * @returns A record mapping each call_id to its output string. Empty when
 *          there are no function_call_output records.
 */
export function buildToolResultMap(records: RolloutLine[]): Record<string, string> {
  const result: Record<string, string> = {};

  for (const record of records) {
    if (record.type !== 'response_item') {
      continue;
    }
    const payload = record.payload;
    if (payload.type === 'function_call_output' && typeof payload.call_id === 'string') {
      result[payload.call_id] = extractOutputString(payload.output);
    }
  }

  return result;
}
