,OAAO,GAAG,IAAA,gBAAS,EAAC;QACxB,IAAI,EAAE,UAAU;QAChB,MAAM,EAAE,QAAQ;QAChB,QAAQ,EAAE,eAAQ,CAAC,GAAG;QACtB,MAAM,EAAE;YACN,KAAK,EAAE,SAAS;YAChB,QAAQ,EAAE,CAAC,EAAE,IAAI,EAAE,MAAM,EAAE,OAAO,EAAE,SAAS,EAAE,CAAC;SACjD;KACF,CAAC,CAAC;IACH,OAAO,CAAC,UAAU,CAAC;QACjB,OAAO,EAAE,CAAC,EAAE,OAAO,EAAE,EAAE,IAAI,EAAE,WAAW,EAAE,OAAO,EAAE,aAAa,EAAE,EAAE,CAAC;KACtE,CAAC,CAAC;IACH,OAAO,CAAC,GAAG,EAAE,CAAC;IAEd,gBAAgB,CAAC,QAAQ,EAAE,OAAO,CAAC,WAAW,CAAC,CAAC,CAAC;IAEjD,QAAQ,CAAC,UAAU,CAAC,aAAa,CAAC,CAAC;IACnC,QAAQ,CAAC,GAAG,EAAE,CAAC;IAEf,MAAM,IAAA,kBAAW,GAAE,CAAC;AACtB,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/codex/src/tracing.ts"],"sourcesContent":["/**\n * MLflow tracing for Codex.\n *\n * This module turns Codex rollout transcripts and agent-turn-complete\n * notification payloads into MLflow traces using the `@mlflow/core` SDK.\n */\n\nimport {\n  init,\n  startSpan,\n  flushTraces,\n  SpanType,\n  SpanStatusCode,\n  TraceMetadataKey,\n  InMemoryTraceManager,\n  type LiveSpan,\n} from '@mlflow/core';\nimport {\n  extractTextFromContent,\n  extractOutputString,\n  parseTimestampToNs,\n} from './transcript';\nimport type { ChatMessage, NotifyPayload, RolloutLine } from './types';\n\n// SDK initialization state.\nlet initialized = false;\n\nconst DEBUG = process.env.MLFLOW_CODEX_DEBUG === 'true';\n\n/**\n * Initialize the MLflow tracing SDK once, using the tracking URI and\n * experiment ID from the environment. Failures are swallowed so that span\n * creation can still proceed (e.g. under test with a mocked SDK).\n */\nfunction ensureInitialized(): void {\n  if (initialized) {\n    return;\n  }\n\n  const trackingUri = process.env.MLFLOW_TRACKING_URI;\n  const experimentId = process.env.MLFLOW_EXPERIMENT_ID;\n\n  if (!trackingUri) {\n    return;\n  }\n\n  try {\n    init({ trackingUri, experimentId });\n    initialized = true;\n  } catch (error) {\n    if (DEBUG) {\n      console.error('[mlflow] Failed to initialize SDK:', error);\n    }\n  }\n}\n\n/**\n * Return the nanosecond timestamp of the `task_started` event in the turn.\n *\n * @param turn The records that make up a single turn.\n * @returns The timestamp in nanoseconds, or null if there is no such event.\n */\nexport function findTaskStartedNs(turn: RolloutLine[]): number | null {\n  for (const record of turn) {\n    if (record.type === 'event_msg' && record.payload.type === 'task_started') {\n      return parseTimestampToNs(record.timestamp);\n    }\n  }\n  return null;\n}\n\n/**\n * Return the nanosecond timestamp of the `task_complete` event in the turn.\n *\n * @param turn The records that make up a single turn.\n * @returns The timestamp in nanoseconds, or null if there is no such event.\n */\nexport function findTaskCompleteNs(turn: RolloutLine[]): number | null {\n  for (const record of turn) {\n    if (record.type === 'event_msg' && record.payload.type === 'task_complete') {\n      return parseTimestampToNs(record.timestamp);\n    }\n  }\n  return null;\n}\n\n/**\n * Scan `exec_command_end` events in the turn and record the failure status of\n * each tool call.\n *\n * @param turn The records that make up a single turn.\n * @returns A map from call_id to `{ failed, exitCode }`.\n */\nexport function buildToolStatuses(\n  turn: RolloutLine[],\n): Record<string, { failed: boolean; exitCode: number }> {\n  const statuses: Record<string, { failed: boolean; exitCode: number }> = {};\n\n  for (const record of turn) {\n    if (record.type !== 'event_msg' || record.payload.type !== 'exec_command_end') {\n      continue;\n    }\n    const payload = record.payload;\n    const callId = payload.call_id;\n    if (typeof callId !== 'string') {\n      continue;\n    }\n    const exitCode = typeof payload.exit_code === 'number' ? payload.exit_code : 0;\n    const failed = payload.status === 'failed' || exitCode !== 0;\n    statuses[callId] = { failed, exitCode };\n  }\n\n  return statuses;\n}\n\n/**\n * Convert transcript response_item records (up to but not including\n * `uptoIndex`) into OpenAI chat-format messages.\n *\n * @param items The records of the turn.\n * @param uptoIndex Exclusive upper bound on the records to convert.\n * @returns The reconstructed conversation history.\n */\nexport function reconstructMessages(items: RolloutLine[], uptoIndex: number): ChatMessage[] {\n  const messages: ChatMessage[] = [];\n  const end = Math.min(uptoIndex, items.length);\n\n  for (let i = 0; i < end; i++) {\n    const record = items[i];\n    if (record.type !== 'response_item') {\n      continue;\n    }\n    const payload = record.payload;\n\n    switch (payload.type) {\n      case 'message': {\n        const text = extractTextFromContent(payload.content);\n        if (text.trim().length === 0) {\n          break;\n        }\n        if (payload.role === 'user') {\n          messages.push({ role: 'user', content: text });\n        } else if (payload.role === 'assistant') {\n          messages.push({ role: 'assistant', content: text });\n        } else if (payload.role === 'developer') {\n          messages.push({ role: 'system', content: text });\n        }\n        break;\n      }\n      case 'function_call': {\n        messages.push({\n          role: 'assistant',\n          content: null,\n          tool_calls: [\n            {\n              id: payload.call_id ?? '',\n              type: 'function',\n              function: {\n                name: payload.name ?? '',\n                arguments: typeof payload.arguments === 'string' ? payload.arguments : '',\n              },\n            },\n          ],\n        });\n        break;\n      }\n      case 'function_call_output': {\n        messages.push({\n          role: 'tool',\n          tool_call_id: payload.call_id ?? '',\n          content: extractOutputString(payload.output),\n        });\n        break;\n      }\n      default:\n        break;\n    }\n  }\n\n  return messages;\n}\n\n/**\n * Parse a JSON arguments string into an object. Returns an empty object when\n * the string is missing or invalid.\n */\nfunction parseArguments(args: unknown): Record<string, unknown> {\n  if (typeof args !== 'string' || args.trim().length === 0) {\n    return {};\n  }\n  try {\n    const parsed = JSON.parse(args) as unknown;\n    if (parsed != null && typeof parsed === 'object') {\n      return parsed as Record<string, unknown>;\n    }\n    return {};\n  } catch {\n    return {};\n  }\n}\n\n/**\n * Create LLM and TOOL child spans from a transcript turn.\n *\n * One LLM span (`llm_call`) is created per assistant message and one TOOL\n * span (`tool_<function_name>`) per function_call, all parented to `parent`.\n *\n * @param parent The parent span (only its `spanId` is required for parenting).\n * @param turn The records that make up a single turn.\n * @param model The model name to attach to LLM span inputs.\n */\nexport function createChildSpans(\n  parent: { spanId: string },\n  turn: RolloutLine[],\n  model: string,\n): void {\n  const taskStartedNs = findTaskStartedNs(turn);\n  const toolStatuses = buildToolStatuses(turn);\n\n  // Pre-index function_call_output records by call_id for tool span timing and\n  // outputs.\n  const outputByCallId: Record<string, { ns: number | null; output: string }> = {};\n  for (const record of turn) {\n    if (record.type !== 'response_item' || record.payload.type !== 'function_call_output') {\n      continue;\n    }\n    const callId = record.payload.call_id;\n    if (typeof callId === 'string') {\n      outputByCallId[callId] = {\n        ns: parseTimestampToNs(record.timestamp),\n        output: extractOutputString(record.payload.output),\n      };\n    }\n  }\n\n  let assistantCount = 0;\n  // Timestamp of the most recent function_call_output seen while walking the\n  // turn in order. Used as the start time for subsequent LLM spans.\n  let prevOutputNs: number | null = null;\n\n  for (let i = 0; i < turn.length; i++) {\n    const record = turn[i];\n    if (record.type !== 'response_item') {\n      continue;\n    }\n    const payload = record.payload;\n\n    if (payload.type === 'message' && payload.role === 'assistant') {\n      const startTimeNs = assistantCount === 0 ? taskStartedNs : prevOutputNs;\n      const endTimeNs = parseTimestampToNs(record.timestamp);\n      const messages = reconstructMessages(turn, i);\n      const content = extractTextFromContent(payload.content);\n\n      const span = startSpan({\n        name: 'llm_call',\n        parent: parent as LiveSpan,\n        spanType: SpanType.LLM,\n        startTimeNs: startTimeNs ?? undefined,\n        inputs: { model, messages },\n      });\n      span.setOutputs({\n        choices: [{ message: { role: 'assistant', content } }],\n      });\n      span.end({ endTimeNs: endTimeNs ?? undefined });\n\n      assistantCount += 1;\n    } else if (payload.type === 'function_call') {\n      const callId = payload.call_id ?? '';\n      const functionName = payload.name ?? 'unknown';\n      const startTimeNs = parseTimestampToNs(record.timestamp);\n      const matched = outputByCallId[callId];\n      const endTimeNs = matched?.ns ?? startTimeNs;\n      const args = parseArguments(payload.arguments);\n\n      const span = startSpan({\n        name: `tool_${functionName}`,\n        parent: parent as LiveSpan,\n        spanType: SpanType.TOOL,\n        startTimeNs: startTimeNs ?? undefined,\n        inputs: args,\n        attributes: {\n          tool_name: functionName,\n          tool_id: callId,\n        },\n      });\n\n      const status = toolStatuses[callId];\n      if (status && status.failed) {\n        span.setStatus(\n          SpanStatusCode.ERROR,\n          `Tool call failed with exit code ${status.exitCode}`,\n        );\n      }\n\n      span.setOutputs({ result: matched?.output ?? '' });\n      span.end({ endTimeNs: endTimeNs ?? undefined });\n    } else if (payload.type === 'function_call_output') {\n      prevOutputNs = parseTimestampToNs(record.timestamp);\n    }\n  }\n}\n\n/**\n * Attach session/user metadata to the trace that owns the given span.\n */\nfunction setTraceMetadata(span: LiveSpan, threadId: string): void {\n  try {\n    const traceManager = InMemoryTraceManager.getInstance();\n    const trace = traceManager.getTrace(span.traceId);\n    if (trace) {\n      trace.info.traceMetadata = {\n        ...trace.info.traceMetadata,\n        [TraceMetadataKey.TRACE_SESSION]: threadId,\n        [TraceMetadataKey.TRACE_USER]: process.env.USER || 'unknown',\n      };\n    }\n  } catch (error) {\n    if (DEBUG) {\n      console.error('[mlflow] Failed to set trace metadata:', error);\n    }\n  }\n}\n\n/**\n * Process an agent-turn-complete notification payload, creating MLflow spans\n * for the completed turn.\n *\n * Creates an AGENT root span (`codex_conversation`) whose input is the last\n * input message (raw string) and whose output is the last assistant message\n * (raw string), plus a single LLM child span (`llm_call`). Sets the\n * `mlflow.trace.session` and `mlflow.trace.user` metadata keys and flushes.\n *\n * When there are no input messages, no spans are created and no flush occurs.\n *\n * @param payload The agent-turn-complete notification payload.\n */\nexport async function processNotify(payload: NotifyPayload): Promise<void> {\n  const inputMessages = payload['input-messages'];\n\n  if (!Array.isArray(inputMessages) || inputMessages.length === 0) {\n    return;\n  }\n\n  ensureInitialized();\n\n  const lastInput = inputMessages[inputMessages.length - 1];\n  const lastAssistant = payload['last-assistant-message'];\n\n  const rootSpan = startSpan({\n    name: 'codex_conversation',\n    spanType: SpanType.AGENT,\n    inputs: lastInput,\n  });\n\n  const llmSpan = startSpan({\n    name: 'llm_call',\n    parent: rootSpan,\n    spanType: SpanType.LLM,\n    inputs: {\n      model: 'unknown',\n      messages: [{ role: 'user', content: lastInput }],\n    },\n  });\n  llmSpan.setOutputs({\n    choices: [{ message: { role: 'assistant', content: lastAssistant } }],\n  });\n  llmSpan.end();\n\n  setTraceMetadata(rootSpan, payload['thread-id']);\n\n  rootSpan.setOutputs(lastAssistant);\n  rootSpan.end();\n\n  await flushTraces();\n}\n"],"version":3}
