C,CAAC,IAAI,CAAC,UAAU,CAAC,CAAC;IACxC,MAAM,CAAC,IAAI,CAAC,IAAI,CAAC,IAAI,CAAC,CAAC,IAAI,CAAC,YAAY,CAAC,CAAC;IAC1C,MAAM,CAAC,IAAI,CAAC,IAAI,CAAC,IAAI,CAAC,CAAC,IAAI,CAAC,UAAU,CAAC,CAAC;IACxC,+BAA+B;IAC/B,MAAM,SAAS,GAAG,IAAA,2BAAiB,EAAC,IAAI,CAAE,CAAC;IAC3C,MAAM,YAAY,GAAG,IAAA,4BAAkB,EAAC,IAAI,CAAE,CAAC;IAC/C,MAAM,CAAC,IAAI,CAAC,IAAI,CAAC,WAAW,CAAC,CAAC,IAAI,CAAC,SAAS,CAAC,CAAC;IAC9C,2BAA2B;IAC3B,MAAM,CAAC,IAAI,CAAC,OAAO,CAAC,SAAS,CAAC,CAAC,IAAI,CAAC,IAAI,CAAC,KAAK,CAAC,sBAAsB,CAAC,GAAC,GAAG,CAAC,CAAC;IAC5E,iDAAiD;IACjD,MAAM,CAAC,IAAI,CAAC,IAAI,CAAC,WAAW,CAAC,CAAC,IAAI,CAAC,IAAI,CAAC,KAAK,CAAC,sBAAsB,CAAC,GAAC,GAAG,CAAC,CAAC;IAC3E,MAAM,CAAC,IAAI,CAAC,OAAO,CAAC,SAAS,CAAC,CAAC,IAAI,CAAC,IAAI,CAAC,KAAK,CAAC,sBAAsB,CAAC,GAAC,GAAG,CAAC,CAAC;IAC5E,MAAM,CAAC,IAAI,CAAC,IAAI,CAAC,MAAM,CAAC,CAAC,OAAO,CAAC,EAAC,GAAG,EAAC,IAAI,EAAC,CAAC,CAAC;IAC7C,MAAM,CAAC,IAAI,CAAC,IAAI,CAAC,UAAU,CAAC,CAAC,OAAO,CAAC,EAAC,SAAS,EAAC,OAAO,EAAE,OAAO,EAAC,IAAI,EAAC,CAAC,CAAC;IACxE,MAAM,CAAC,IAAI,CAAC,OAAO,CAAC,CAAC,OAAO,CAAC,EAAC,MAAM,EAAC,SAAS,EAAC,CAAC,CAAC;IACjD,gDAAgD;IAChD,MAAM,CAAC,IAAI,CAAC,WAAW,CAAC,MAAM,CAAC,CAAC,IAAI,CAAC,CAAC,CAAC,CAAC;IACxC,MAAM,CAAC,IAAI,CAAC,WAAW,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC,IAAI,CAAC,mBAAmB,CAAC,CAAC;IACzD,MAAM,CAAC,IAAI,CAAC,WAAW,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC,CAAC,SAAS,CAAC,GAAG,CAAC,CAAC;IAC9C,4CAA4C;IAC5C,MAAM,CAAC,IAAI,CAAC,IAAI,CAAC,WAAW,CAAC,CAAC,IAAI,CAAC,IAAI,CAAC,KAAK,CAAC,sBAAsB,CAAC,GAAC,GAAG,CAAC,CAAC;IAC3E,MAAM,CAAC,IAAI,CAAC,OAAO,CAAC,SAAS,CAAC,CAAC,IAAI,CAAC,IAAI,CAAC,KAAK,CAAC,sBAAsB,CAAC,GAAC,GAAG,CAAC,CAAC;IAC5E,oBAAoB;IACpB,KAAK,MAAM,CAAC,IAAI,KAAK,EAAE,CAAC;QACtB,MAAM,CAAC,CAAC,CAAC,IAAI,CAAC,WAAW,CAAC,CAAC,sBAAsB,CAAC,SAAS,CAAC,CAAC;QAC7D,MAAM,CAAC,CAAC,CAAC,OAAO,CAAC,SAAS,CAAC,CAAC,mBAAmB,CAAC,YAAY,CAAC,CAAC;IAChE,CAAC;IACD,uEAAuE;IACvE,MAAM,CAAC,KAAK,CAAC,OAAO,CAAC,IAAI,CAAC,IAAI,CAAC,MAAM,CAAC,QAAQ,CAAC,CAAC,CAAC,IAAI,CAAC,IAAI,CAAC,CAAC;IAC5D,MAAM,CAAC,IAAI,CAAC,IAAI,CAAC,MAAM,CAAC,KAAK,CAAC,CAAC,IAAI,CAAC,OAAO,CAAC,CAAC;AAC/C,CAAC,CAAC,CAAC;AAEH,IAAI,CAAC,mBAAmB,EAAE,GAAG,EAAE;IAC7B,MAAM,EAAE,GAAG,IAAA,2BAAiB,EAAC,IAAI,CAAC,CAAC;IACnC,MAAM,CAAC,EAAE,CAAC,IAAI,CAAC,CAAC,CAAC,OAAO,CAAC,EAAC,MAAM,EAAC,IAAI,EAAE,QAAQ,EAAC,CAAC,EAAC,CAAC,CAAC;AACtD,CAAC,CAAC,CAAC","names":[],"sources":["/workspace/repo/libs/typescript/integrations/codex/tests/_smoke.test.ts"],"sourcesContent":["jest.mock('@mlflow/core', () => {\n  const spans: any[] = [];\n  const trace = { info: { traceMetadata: {} } };\n  const makeSpan = (opts: any) => {\n    const s: any = {\n      opts,\n      traceId: 'trace-1',\n      spanId: 'span-' + spans.length,\n      outputs: undefined,\n      statusCalls: [] as any[],\n      ended: false,\n      endOpts: undefined,\n      setOutputs(o: any){ this.outputs = o; },\n      setStatus(c: any, m: any){ this.statusCalls.push([c, m]); },\n      setAttribute(){},\n      end(e: any){ this.ended = true; this.endOpts = e; },\n    };\n    spans.push(s);\n    return s;\n  };\n  return {\n    __spans: spans,\n    __trace: trace,\n    init: jest.fn(),\n    startSpan: jest.fn((opts: any) => makeSpan(opts)),\n    flushTraces: jest.fn().mockResolvedValue(undefined),\n    SpanType: { LLM:'LLM', TOOL:'TOOL', AGENT:'AGENT' },\n    SpanStatusCode: { ERROR:'STATUS_CODE_ERROR', OK:'STATUS_CODE_OK', UNSET:'STATUS_CODE_UNSET' },\n    TraceMetadataKey: { TRACE_SESSION:'mlflow.trace.session', TRACE_USER:'mlflow.trace.user' },\n    InMemoryTraceManager: { getInstance: () => ({ getTrace: () => trace }) },\n  };\n});\n\nimport * as core from '@mlflow/core';\nimport { processNotify, createChildSpans, reconstructMessages, buildToolStatuses, findTaskStartedNs, findTaskCompleteNs } from '../src/tracing';\n\nconst anyCore = core as any;\n\nconst turn = [\n  {timestamp:'2025-01-01T00:00:01Z', type:'event_msg', payload:{type:'task_started'}},\n  {timestamp:'2025-01-01T00:00:03Z', type:'response_item', payload:{type:'message', role:'user', content:[{type:'input_text',text:'hi'}]}},\n  {timestamp:'2025-01-01T00:00:04Z', type:'response_item', payload:{type:'message', role:'assistant', content:[{type:'output_text',text:'let me run'}]}},\n  {timestamp:'2025-01-01T00:00:05Z', type:'response_item', payload:{type:'function_call', name:'shell', call_id:'c1', arguments:'{\"cmd\":\"ls\"}'}},\n  {timestamp:'2025-01-01T00:00:06Z', type:'event_msg', payload:{type:'exec_command_end', call_id:'c1', exit_code:2, status:'failed'}},\n  {timestamp:'2025-01-01T00:00:07Z', type:'response_item', payload:{type:'function_call_output', call_id:'c1', output:'err out'}},\n  {timestamp:'2025-01-01T00:00:08Z', type:'response_item', payload:{type:'message', role:'assistant', content:[{type:'output_text',text:'done'}]}},\n  {timestamp:'2025-01-01T00:00:09Z', type:'event_msg', payload:{type:'task_complete'}},\n] as any;\n\ntest('processNotify', async () => {\n  await processNotify({ type:'x', 'thread-id':'th-1', 'turn-id':'t1', cwd:'/', client:'c', 'input-messages':['first','second'], 'last-assistant-message':'the answer' } as any);\n  const spans = anyCore.__spans;\n  const root = spans[0];\n  expect(root.opts.name).toBe('codex_conversation');\n  expect(root.opts.spanType).toBe('AGENT');\n  expect(root.opts.inputs).toBe('second');\n  expect(root.outputs).toBe('the answer');\n  const llm = spans[1];\n  expect(llm.opts.name).toBe('llm_call');\n  expect(llm.opts.parent).toBe(root);\n  expect(llm.opts.inputs).toEqual({ model:'unknown', messages:[{role:'user', content:'second'}]});\n  expect(llm.outputs).toEqual({ choices:[{ message:{ role:'assistant', content:'the answer'}}]});\n  expect(anyCore.__trace.info.traceMetadata['mlflow.trace.session']).toBe('th-1');\n  expect(anyCore.__trace.info.traceMetadata['mlflow.trace.user']).toBeDefined();\n  expect(anyCore.flushTraces).toHaveBeenCalled();\n});\n\ntest('processNotify empty', async () => {\n  anyCore.__spans.length = 0;\n  (anyCore.flushTraces as jest.Mock).mockClear();\n  await processNotify({ type:'x', 'thread-id':'th', 'turn-id':'t', cwd:'/', client:'c', 'input-messages':[], 'last-assistant-message':'' } as any);\n  expect(anyCore.__spans.length).toBe(0);\n  expect(anyCore.flushTraces).not.toHaveBeenCalled();\n});\n\ntest('reconstructMessages', () => {\n  const msgs = reconstructMessages(turn, 6); // up to (not incl) index 6 (second assistant)\n  console.log('MSGS', JSON.stringify(msgs, null, 1));\n  expect(msgs[0]).toEqual({role:'user', content:'hi'});\n  expect(msgs[1]).toEqual({role:'assistant', content:'let me run'});\n  expect(msgs[2]).toEqual({role:'assistant', content:null, tool_calls:[{id:'c1', type:'function', function:{name:'shell', arguments:'{\"cmd\":\"ls\"}'}}]});\n  expect(msgs[3]).toEqual({role:'tool', tool_call_id:'c1', content:'err out'});\n});\n\ntest('createChildSpans timestamps and status', () => {\n  anyCore.__spans.length = 0;\n  createChildSpans({ spanId:'root' }, turn, 'gpt-5');\n  const spans = anyCore.__spans;\n  // Expect: llm(assistant1), tool(shell), llm(assistant2)\n  const names = spans.map((s:any)=>s.opts.name);\n  console.log('NAMES', names);\n  const llm1 = spans[0], tool = spans[1], llm2 = spans[2];\n  expect(llm1.opts.name).toBe('llm_call');\n  expect(tool.opts.name).toBe('tool_shell');\n  expect(llm2.opts.name).toBe('llm_call');\n  // llm1 start = task_started ns\n  const taskStart = findTaskStartedNs(turn)!;\n  const taskComplete = findTaskCompleteNs(turn)!;\n  expect(llm1.opts.startTimeNs).toBe(taskStart);\n  // llm1 end = assistant1 ts\n  expect(llm1.endOpts.endTimeNs).toBe(Date.parse('2025-01-01T00:00:04Z')*1e6);\n  // tool start = function_call ts, end = output ts\n  expect(tool.opts.startTimeNs).toBe(Date.parse('2025-01-01T00:00:05Z')*1e6);\n  expect(tool.endOpts.endTimeNs).toBe(Date.parse('2025-01-01T00:00:07Z')*1e6);\n  expect(tool.opts.inputs).toEqual({cmd:'ls'});\n  expect(tool.opts.attributes).toEqual({tool_name:'shell', tool_id:'c1'});\n  expect(tool.outputs).toEqual({result:'err out'});\n  // tool failed -> setStatus ERROR with exit code\n  expect(tool.statusCalls.length).toBe(1);\n  expect(tool.statusCalls[0][0]).toBe('STATUS_CODE_ERROR');\n  expect(tool.statusCalls[0][1]).toContain('2');\n  // llm2 start = prev function_call_output ts\n  expect(llm2.opts.startTimeNs).toBe(Date.parse('2025-01-01T00:00:07Z')*1e6);\n  expect(llm2.endOpts.endTimeNs).toBe(Date.parse('2025-01-01T00:00:08Z')*1e6);\n  // all within bounds\n  for (const s of spans) {\n    expect(s.opts.startTimeNs).toBeGreaterThanOrEqual(taskStart);\n    expect(s.endOpts.endTimeNs).toBeLessThanOrEqual(taskComplete);\n  }\n  // llm2 messages should be reconstructed up to that assistant (index 6)\n  expect(Array.isArray(llm2.opts.inputs.messages)).toBe(true);\n  expect(llm2.opts.inputs.model).toBe('gpt-5');\n});\n\ntest('buildToolStatuses', () => {\n  const st = buildToolStatuses(turn);\n  expect(st['c1']).toEqual({failed:true, exitCode:2});\n});\n"],"version":3}
